'use strict';
const IoTVisuals=(()=>{
const ic=n=>`<i class="ph ph-${n}" aria-hidden="true"></i>`;
const n=(id,x,y,label,icon,sub='',tone='')=>({id,x,y,label,icon,sub,tone});
const e=(from,to,type='wireless',flow=true,extra={})=>({from,to,type,flow,...extra});
function diagram(title,nodes,edges,regions=[],caption='Packets show a simplified data path; links can carry traffic both ways.',background=''){
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const byId=Object.fromEntries(nodes.map(n=>[n.id,n]));
const lines=edges.map((l,i)=>{const a=byId[l.from],b=byId[l.to],d=l.path||`M ${a.x} ${a.y} L ${b.x} ${b.y}`;return `<path class="network-link ${l.type} ${l.broken?'broken':''}" d="${d}"/>${l.label?`<text class="network-link-label" x="${l.lx??(a.x+b.x)/2}" y="${l.ly??((a.y+b.y)/2-12)}" text-anchor="middle">${l.label}</text>`:''}${l.flow&&!l.broken&&!reduced?`<circle r="4" opacity="0" class="network-packet ${l.type}"><set attributeName="opacity" to="1" begin="${i*.3}s"/><animateMotion dur="${2.2+i*.25}s" begin="${i*.3}s" repeatCount="indefinite" path="${d}"/></circle>`:''}${l.broken?`<text class="network-cut" x="${l.cutX??(a.x+b.x)/2}" y="${l.cutY??((a.y+b.y)/2+5)}" text-anchor="middle">×</text>`:''}`}).join('');
return `<figure class="network-figure"><div class="network-map" role="img" aria-label="${title}: ${nodes.map(x=>x.label+(x.sub?' ('+x.sub+')':'')).join(', ')}. ${edges.map(l=>byId[l.from].label+' to '+byId[l.to].label+' via '+l.type+(l.broken?', disconnected':'')).join('; ')}">${regions.map(r=>`<div class="network-region" style="left:${r.x/9}%;top:${r.y/3.1}%;width:${r.w/9}%;height:${r.h/3.1}%"><span>${r.label}</span></div>`).join('')}<svg class="network-wires" viewBox="0 0 900 310" preserveAspectRatio="none" aria-hidden="true">${background}${lines}</svg>${nodes.map(x=>`<div class="network-node ${x.tone}" style="left:${x.x/9}%;top:${x.y/3.1}%"><div class="network-icon">${ic(x.icon)}</div><strong>${x.label}</strong>${x.sub?`<small>${x.sub}</small>`:''}</div>`).join('')}</div><div class="network-legend"><span class="legend-wireless">Radio link</span><span class="legend-wired">Wired link</span><span class="legend-backhaul">IP backhaul</span></div><figcaption>${caption}</figcaption></figure>`;
}
function connection(v){
const cloud=n('app',825,145,'Application','cloud','Uses the reading','purple');
if(v==='wifi')return diagram('Wi-Fi star network',[n('sensor',85,80,'Sensor','thermometer-simple','Wi-Fi'),n('camera',85,215,'Camera','video-camera','Wi-Fi'),n('ap',330,145,'AP / router','wifi-high','Home network'),n('internet',590,145,'Internet','globe','WAN connection','purple'),cloud],[e('sensor','ap'),e('camera','ap'),e('ap','internet','backhaul',true,{label:'WAN',ly:126}),e('internet','app','backhaul')],[{x:18,y:24,w:410,h:267,label:'LOCAL NETWORK'}]);
if(v==='ble')return diagram('Bluetooth LE peripheral to central',[n('sensor',100,85,'Wearable','watch','Peripheral'),n('other',100,215,'Sensor','thermometer-simple','Peripheral'),n('phone',425,145,'Phone','device-mobile','Central + local app'),n('internet',650,145,'Internet','globe','Optional','purple'),cloud],[e('sensor','phone'),e('other','phone'),e('phone','internet','backhaul',false,{label:'optional upload',ly:120}),e('internet','app','backhaul',false)],[{x:25,y:24,w:480,h:267,label:'BLUETOOTH LE CONNECTIONS'}],'The phone can use readings locally. Cloud upload is optional; Bluetooth LE also supports other topologies.');
if(v==='zigbee')return diagram('Zigbee mesh with IP gateway',[n('sensor',70,80,'Sensor','thermometer-simple','End device'),n('door',70,225,'Door sensor','door','End device'),n('r1',260,80,'Powered router','lightbulb','Relays data'),n('r2',260,225,'Powered router','plugs','Relays data'),n('hub',495,145,'Coordinator','graph','Hub / IP gateway'),n('internet',665,145,'IP network','globe','Backhaul','purple'),cloud],[e('sensor','r1'),e('door','r2'),e('r1','r2','wireless',false),e('r1','hub'),e('r2','hub'),e('hub','internet','backhaul'),e('internet','app','backhaul')],[{x:16,y:24,w:550,h:270,label:'ZIGBEE MESH'}],'Powered Zigbee routers can relay. Battery end devices do not relay. The coordinator and IP gateway are combined here.');
if(v==='lora')return diagram('LoRaWAN star of stars',[n('sensor',65,80,'Field sensor','plant','LoRa radio'),n('meter',65,220,'Water meter','drop','LoRa radio'),n('g1',275,80,'Gateway A','broadcast','Forwards packets'),n('g2',275,220,'Gateway B','broadcast','Forwards packets'),n('ns',580,145,'Network server','database','Filters duplicates','purple'),n('app',820,145,'Application server','cloud','Uses the reading','purple')],[e('sensor','g1'),e('sensor','g2','wireless',false),e('meter','g2'),e('meter','g1','wireless',false),e('g1','ns','backhaul',true,{label:'IP',lx:430,ly:98}),e('g2','ns','backhaul'),e('ns','app','backhaul')],[{x:12,y:22,w:347,h:271,label:'LoRa RADIO'},{x:498,y:70,w:387,h:150,label:'SERVER FUNCTIONS'}],'Nearby gateways may hear the same packet. Gateways forward it over IP; the network server removes duplicates.');
if(v==='cell')return diagram('Cellular network',[n('sensor',75,80,'Tracker','map-pin','Cellular modem'),n('meter',75,220,'Remote sensor','thermometer-simple','Cellular modem'),n('tower',285,145,'Base station','cell-tower','Radio access'),n('core',470,145,'Operator core','database','SIM / service','purple'),n('internet',650,145,'Internet','globe','','purple'),cloud],[e('sensor','tower'),e('meter','tower'),e('tower','core','backhaul'),e('core','internet','backhaul'),e('internet','app','backhaul')],[{x:210,y:34,w:336,h:237,label:'OPERATOR NETWORK'}]);
return diagram('Ethernet local area network',[n('sensor',70,80,'Sensor','thermometer-simple','Ethernet port'),n('camera',70,220,'Camera','video-camera','Ethernet port'),n('switch',295,145,'Switch','plugs-connected','Local network'),n('local',500,230,'Local server','desktop','LAN application'),n('router',500,80,'Router','arrows-left-right','WAN gateway'),n('internet',675,80,'Internet','globe','','purple'),n('app',835,80,'Cloud app','cloud','Optional','purple')],[e('sensor','switch','wired'),e('camera','switch','wired'),e('switch','local','wired'),e('switch','router','wired'),e('router','internet','backhaul'),e('internet','app','backhaul')],[{x:12,y:20,w:548,h:273,label:'WIRED LAN'}],'The switch joins local devices. A router provides a path to other networks; the local server works without the internet.');
}
function watering(on){return `<div class="watering-visual ${on?'water-on':'water-off'}" role="img" aria-label="${on?'Pump on: animated water flowing into the soil':'Pump off: water supply cut off, no water flows'}"><img src="assets/plant.png" alt="Smart pot with a soil sensor"><svg class="irrigation" viewBox="0 0 360 260" aria-hidden="true"><path class="water-pipe" d="M350 66 H285 Q255 66 255 88 V95"/><path class="pipe-inner" d="M350 66 H285 Q255 66 255 88 V95"/><path class="water-in-pipe" d="M350 66 H285 Q255 66 255 88 V95"/><path class="water-stream" d="M255 96 Q244 109 222 121"/><path class="water-droplet droplet-a" d="M248 101 Q251 106 248 109 Q245 106 248 101Z"/><path class="water-droplet droplet-b" d="M237 112 Q240 117 237 120 Q234 117 237 112Z"/><path class="water-splash" d="M220 122 l-8-5 M224 124 l9-8 M221 126 l-11 2"/><circle class="water-valve" cx="315" cy="66" r="10"/><path class="valve-handle" d="${on?'M309 66 H321':'M315 60 V72'}"/></svg><div class="water-state">${ic(on?'drop':'drop-slash')} Water ${on?'flowing':'stopped'}</div></div>`}
function housePlan(wall=false){return `<rect class="location-floor" x="25" y="25" width="850" height="260" rx="12"/><rect class="room-fill" x="35" y="35" width="365" height="240" rx="6"/><rect class="room-fill second-room" x="490" y="35" width="375" height="240" rx="6"/><path class="house-wall" d="M420 28V105 M420 148V284 M480 28V105 M480 148V284"/><path class="door-swing" d="M420 106Q463 106 463 149"/><text class="location-label" x="60" y="53">LIVING ROOM</text><text class="location-label" x="495" y="53">BEDROOM</text>${wall?'<path class="obstacle-wall" d="M447 70V242"/><text class="location-label obstacle-label" x="447" y="265" text-anchor="middle">THICK WALL</text>':'<text class="location-label" x="450" y="269" text-anchor="middle">OPEN DOORWAY</text>'}`}
function farmPlan(){return `<rect class="location-floor" x="20" y="25" width="405" height="260" rx="14"/><path class="crop-row" d="M38 74H404 M38 90H404 M38 220H404 M38 238H404 M38 257H404"/><path class="farm-track" d="M38 166H404"/><text class="location-label" x="42" y="50">FARM / FIELD</text><rect class="server-site" x="494" y="50" width="390" height="235" rx="14"/><text class="location-label" x="515" y="75">REMOTE SERVER SITE</text>`}
function mesh(relay){return diagram('Zigbee mesh in a home, with a relay around an obstacle',[n('sensor',105,195,'Door sensor','door','End device'),n('r1',285,90,'Smart plug','plugs','Powered router'),n('relay',570,95,'Lamp relay','lightbulb',relay?'Powered router':'Not installed',relay?'':'offline'),n('hub',780,195,'Home hub','graph',relay?'Coordinator + gateway':'Coordinator, waiting',relay?'':'offline')],[e('sensor','hub','wireless',false,{broken:true,label:'Direct route blocked',lx:420,ly:215}),e('sensor','r1'),e('r1','relay','wireless',relay,{broken:!relay,path:'M285 90 L380 60 L520 60 L570 95'}),e('relay','hub','wireless',relay,{broken:!relay}),e('r1','hub','wireless',false,{broken:true,path:'M285 90 L780 195',cutX:447,cutY:129})],[],relay?'Alternate route: door sensor → smart plug → lamp relay → home hub. Only powered routers forward messages.':'The sensor reaches the smart plug, but the thick dividing wall blocks the route to the hub.',housePlan(true));}
function range(wall){const bg=housePlan(wall)+`<path class="radio-wave ${wall?'faint':''}" d="M215 120Q250 170 215 220 M240 100Q294 170 240 240 M265 80Q336 170 265 260"/>`;return diagram('Bluetooth range shown on a home floor plan',[n('sensor',150,160,'BLE sensor','bluetooth','Living room'),n('phone',740,160,'Phone','device-mobile',wall?'No reading':'Reading received',wall?'offline':'')],[e('sensor','phone','wireless',!wall,{broken:wall,label:wall?'Signal lost here':'Clear radio path',lx:447,ly:132})],[],wall?'A thick wall blocks this illustrative link. It is not a universal range limit or a coverage prediction.':'The signal crosses an open doorway. Actual range depends on distance, materials and radio settings.',bg);}
function bandwidth(video){const bg=farmPlan()+`<path class="capacity-channel" d="M214 122L235 133L235 157L214 169 M260 122L239 133L239 157L260 169"/><text class="location-label" x="237" y="196" text-anchor="middle">LOW DATA RATE</text>${video?'<rect class="queued-packet" x="174" y="124" width="14" height="12" rx="2"/><rect class="queued-packet" x="153" y="140" width="14" height="12" rx="2"/><rect class="queued-packet" x="174" y="156" width="14" height="12" rx="2"/>':''}`;return diagram('Data rate bottleneck from farm to remote server',[n('device',90,145,video?'Field camera':'Soil sensor',video?'video-camera':'plant',video?'Large video stream':'Small reading'),n('gateway',340,145,'Farm gateway','broadcast','LoRaWAN radio'),n('server',595,145,'Network server','database','IP backhaul','purple'),n('app',805,145,'Farm dashboard','cloud',video?'Video cannot fit':'Reading received',video?'offline':'purple')],[e('device','gateway','wireless',!video),e('gateway','server','backhaul',!video),e('server','app','backhaul',!video)],[],video?'The radio is the bottleneck: video creates more data than this low-rate link can carry.':'A small reading fits through the low-rate radio link. Wider IP backhaul carries it onward.',bg);}
function poe(on){const bg=`<rect class="location-floor" x="20" y="24" width="860" height="264" rx="14"/><rect class="room-fill" x="30" y="34" width="290" height="244" rx="8"/><path class="house-wall" d="M330 27V285"/><text class="location-label" x="45" y="54">NETWORK CABINET</text><text class="location-label" x="395" y="54">BUILDING CORRIDOR</text>`;return diagram('PoE camera in a building corridor',[n('recorder',165,225,'Video recorder','desktop','Local LAN'),n('switch',165,105,on?'PoE switch':'Network switch','plugs-connected',on?'Data + power source':'Data only'),n('camera',705,145,'IP camera','video-camera',on?'Powered & online':'No power adapter',on?'':'offline')],[e('switch','recorder','wired',on),e('camera','switch','wired',on,{path:'M705 145 L520 145 L520 105 L165 105',label:'One Ethernet cable',lx:447,ly:92}),...(on?[e('switch','camera','power',true,{path:'M165 123 L505 123 L505 163 L705 163',label:'Power',lx:580,ly:195})]:[])],[],on?'The powered switch supplies the compatible camera. Video returns over the same cable to the local recorder.':'The cable is installed, but this camera still needs a power source.',bg);}
function edge(local,online){const bg=`<rect class="location-floor" x="20" y="137" width="860" height="158" rx="14"/><text class="location-label" x="42" y="160">ON-SITE DOOR CONTROL</text><rect class="server-site" x="500" y="15" width="310" height="115" rx="12"/><text class="location-label" x="516" y="38">REMOTE CLOUD</text>`;return diagram('Door control with local and remote paths',[n('sensor',100,210,'Door sensor','door','On-site input'),n('controller',355,210,'Local controller','cpu',local?'Makes decision':'Asks cloud'),n('cloud',655,70,'Cloud service','cloud',online?'Internet available':'Offline',online?'purple':'offline'),n('lock',800,210,'Door lock','lock-open',local||online?'Responds':'Waiting',local||online?'':'offline')],[e('sensor','controller','wired'),e('controller','cloud','backhaul',!local&&online,{broken:!online}),e('cloud','controller','backhaul',!local&&online,{broken:!online,path:'M655 85 Q590 165 355 225'}),e('controller','lock','wired',local||online)],[],local?'The local path stays inside the building, so an internet outage does not stop this control loop.':'The remote path must carry a request out and return a decision before the lock responds.',bg);}
return {connection,watering,mesh,range,bandwidth,poe,edge};
})();
